import json
from itertools import product

def solve():
    # Categories and values
    categories = {
        "Name": ["Eric", "Peter", "Arnold", "Alice", "Bob"],
        "Lunch": ["stir fry", "spaghetti", "stew", "grilled cheese", "pizza"],
        "Car": ["ford f150", "tesla model 3", "bmw 3 series", "toyota camry", "honda civic"],
        "Phone": ["iphone 13", "google pixel 6", "samsung galaxy s21", "oneplus 9", "huawei p50"],
        "Occupation": ["teacher", "lawyer", "doctor", "artist", "engineer"],
        "Drink": ["tea", "milk", "water", "root beer", "coffee"],
    }

    houses = [1, 2, 3, 4, 5]

    # Map value -> category
    value_to_category = {}
    for cat, vals in categories.items():
        for v in vals:
            value_to_category[v] = cat

    # All values list
    all_values = [v for vals in categories.values() for v in vals]

    # Position mapping: value -> house index (1..5) or None if unassigned
    pos = {v: None for v in all_values}

    # Helper constraints list
    equal_pairs = []
    left_of_pairs = []
    next_left_pairs = []
    not_at_list = []
    fixed_list = []
    dist_pairs = []

    def equal(a, b):
        equal_pairs.append((a, b))

    def left_of(a, b):
        left_of_pairs.append((a, b))

    def next_left(a, b):
        next_left_pairs.append((a, b))

    def not_at(a, h):
        not_at_list.append((a, h))

    def fixed(a, h):
        fixed_list.append((a, h))

    def distance_exact(a, b, d):
        dist_pairs.append((a, b, d))

    # Constraints from the puzzle:
    # 1. root beer <-> honda civic
    equal("root beer", "honda civic")
    # 2. milk directly left of grilled cheese
    next_left("milk", "grilled cheese")
    # 3. Alice uses Samsung Galaxy S21
    equal("Alice", "samsung galaxy s21")
    # 4. Alice loves stir fry
    equal("Alice", "stir fry")
    # 5. Tea not in fifth house
    not_at("tea", 5)
    # 6. BMW left of tea
    left_of("bmw 3 series", "tea")
    # 7. Doctor is Arnold
    equal("Arnold", "doctor")
    # 8. iPhone 13 is coffee drinker
    equal("iphone 13", "coffee")
    # 9. Engineer is BMW
    equal("engineer", "bmw 3 series")
    # 10. Stew is iPhone13
    equal("stew", "iphone 13")
    # 11. Doctor directly left of OnePlus 9
    next_left("doctor", "oneplus 9")
    # 12. Honda Civic directly left of spaghetti
    next_left("honda civic", "spaghetti")
    # 13. Google Pixel 6 is tea drinker
    equal("google pixel 6", "tea")
    # 14. Alice is artist
    equal("Alice", "artist")
    # 15. One house between Alice and Ford F-150
    distance_exact("Alice", "ford f150", 2)
    # 16. Arnold owns Toyota Camry
    equal("Arnold", "toyota camry")
    # 17. Eric is in the fourth house
    fixed("Eric", 4)
    # 18. OnePlus 9 is lawyer
    equal("oneplus 9", "lawyer")
    # 19. Grilled cheese is Peter
    equal("grilled cheese", "Peter")

    # Constraint checking
    def unique_category_check():
        # For each category, ensure no two values in same category share the same assigned house
        for cat, vals in categories.items():
            seen = {}
            for v in vals:
                h = pos[v]
                if h is not None:
                    if h in seen:
                        return False
                    seen[h] = v
        return True

    def check_equalities():
        for a, b in equal_pairs:
            pa, pb = pos[a], pos[b]
            if pa is not None and pb is not None and pa != pb:
                return False
        return True

    def check_left_of():
        for a, b in left_of_pairs:
            pa, pb = pos[a], pos[b]
            if pa is not None and pb is not None:
                if not (pa < pb):
                    return False
            elif pa is not None and pb is None:
                # a is placed, b must be somewhere to the right; if a is at 5, impossible
                if pa == 5:
                    return False
            elif pa is None and pb is not None:
                # b is placed, a must be somewhere to the left; if b is at 1, impossible
                if pb == 1:
                    return False
        return True

    def check_next_left():
        for a, b in next_left_pairs:
            pa, pb = pos[a], pos[b]
            if pa is not None and pb is not None:
                if pa + 1 != pb:
                    return False
            elif pa is not None and pb is None:
                if pa == 5:
                    return False
            elif pa is None and pb is not None:
                if pb == 1:
                    return False
        return True

    def check_not_at():
        for a, h in not_at_list:
            pa = pos[a]
            if pa is not None and pa == h:
                return False
        return True

    def check_fixed():
        for a, h in fixed_list:
            pa = pos[a]
            if pa is not None and pa != h:
                return False
        return True

    def check_distance():
        for a, b, d in dist_pairs:
            pa, pb = pos[a], pos[b]
            if pa is not None and pb is not None:
                if abs(pa - pb) != d:
                    return False
            elif pa is not None and pb is None:
                # pb must be either pa-d or pa+d within 1..5; if both out-of-range, impossible
                candidates = []
                if 1 <= pa - d <= 5:
                    candidates.append(pa - d)
                if 1 <= pa + d <= 5:
                    candidates.append(pa + d)
                if not candidates:
                    return False
            elif pa is None and pb is not None:
                candidates = []
                if 1 <= pb - d <= 5:
                    candidates.append(pb - d)
                if 1 <= pb + d <= 5:
                    candidates.append(pb + d)
                if not candidates:
                    return False
        return True

    def check_all():
        return (unique_category_check()
                and check_equalities()
                and check_left_of()
                and check_next_left()
                and check_not_at()
                and check_fixed()
                and check_distance())

    # Helper: compute list of possible houses for a value given current assignment
    def possible_houses_for_value(v):
        if pos[v] is not None:
            return [pos[v]]
        cat = value_to_category[v]
        # Houses already used by other values in the same category are not allowed
        used_houses = set()
        for w in categories[cat]:
            if w != v and pos[w] is not None:
                used_houses.add(pos[w])

        candidates = []
        for h in houses:
            if h in used_houses:
                continue
            # Temporary assign and check local constraints
            pos[v] = h
            if check_all():
                candidates.append(h)
            pos[v] = None
        return candidates

    # Pre-assign fixed positions from 'fixed' constraints to reduce search
    for a, h in fixed_list:
        if pos[a] is None:
            pos[a] = h
        elif pos[a] != h:
            # Contradiction (shouldn't happen given puzzle is consistent)
            pass

    # Variable ordering: prioritize constrained values
    priority_values = [
        # Names with direct constraints
        "Eric", "Arnold", "Alice", "Peter",
        # Phones with direct ties
        "oneplus 9", "google pixel 6", "samsung galaxy s21", "iphone 13",
        # Occupations with ties
        "doctor", "lawyer", "artist", "engineer",
        # Drinks with ties
        "tea", "milk", "root beer", "coffee",
        # Lunch ties
        "grilled cheese", "stew", "spaghetti", "stir fry",
        # Cars with ties
        "toyota camry", "bmw 3 series", "honda civic", "ford f150",
    ]
    # Complete value ordering: prioritized ones first, then the rest
    ordered_values = []
    seen = set()
    for v in priority_values:
        if v in pos and v not in seen:
            ordered_values.append(v)
            seen.add(v)
    for v in all_values:
        if v not in seen:
            ordered_values.append(v)
            seen.add(v)

    # Backtracking search with MRV (minimum remaining values)
    def select_unassigned_variable():
        # Choose the unassigned value with the fewest possible houses
        best_v = None
        best_options = None
        for v in ordered_values:
            if pos[v] is None:
                options = possible_houses_for_value(v)
                if best_options is None or len(options) < len(best_options):
                    best_v = v
                    best_options = options
                if best_options is not None and len(best_options) == 1:
                    break
        return best_v, (possible_houses_for_value(best_v) if best_v is not None else [])

    solution_found = False

    def backtrack():
        nonlocal solution_found
        if solution_found:
            return True
        # If all assigned, success
        if all(pos[v] is not None for v in all_values):
            if check_all():
                solution_found = True
                return True
            return False

        v, options = select_unassigned_variable()
        if v is None:
            return False
        for h in options:
            pos[v] = h
            if check_all():
                if backtrack():
                    return True
            pos[v] = None
        return False

    if not backtrack():
        raise RuntimeError("No solution found")

    # Build rows per house
    header = ["House", "Name", "Lunch", "Car", "Phone", "Occupation", "Drink"]
    rows = []
    for h in houses:
        row = [str(h)]
        for cat in ["Name", "Lunch", "Car", "Phone", "Occupation", "Drink"]:
            # find the value in this category at house h
            val = None
            for v in categories[cat]:
                if pos[v] == h:
                    val = v
                    break
            row.append(val)
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, indent=2))
